<# Pure host guards and WhatIf only. No VM, native device, process launch or file writes. #>
[CmdletBinding()]param()
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$script:checks=0
function Check([bool]$Value,[string]$Name){if(-not$Value){throw $Name};$script:checks++}
function Reject([scriptblock]$Body,[string]$Name){$failed=$false;try{&$Body|Out-Null}catch{$failed=$true};Check $failed $Name}
function Clone($Value){$Value|ConvertTo-Json -Depth 32|ConvertFrom-Json}
$workspace=Split-Path -Parent $PSScriptRoot;$path=Join-Path $workspace 'scripts\Invoke-LabNativeReconstruct.ps1';$tokens=$null;$errors=$null
$ast=[Management.Automation.Language.Parser]::ParseFile($path,[ref]$tokens,[ref]$errors);Check ($errors.Count-eq0) 'host source parses'
foreach($f in $ast.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]},$false)){. ([scriptblock]::Create($f.Extent.Text))}
Import-RHFunctions ([IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'guest\Invoke-GuestNativeReconstruct.ps1'))) @('Assert-NRFields','Assert-NRBool','Assert-NRNumber','Assert-NRHash','Assert-NRGuid','Assert-NRSame')
Import-RHFunctions ([IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'guest\Invoke-GuestNativeProbe.ps1'))) @('Assert-NativeProbeGuid')
$run='a'*32;$phase='b'*32;$requestHash='1'*64;$pinHash='2'*64;$ticketHash='3'*64;$binaryHash='4'*64
$request=[pscustomobject]@{example='pure-host-fixture'};$caseRoot='C:\ntfs2refs\native-reconstruct\'+$run+'\'+$phase
$review=[pscustomobject]@{schemaVersion=1;kind='native-reconstruction-reviewed-sources';files=@(Get-RHSources|ForEach-Object{[pscustomobject]@{path=$_;sha256=('5'*64)}})}
Assert-RHReviewed $review;$script:checks++
foreach($change in @({param($x)$x.kind='other'},{param($x)$x.files=@($x.files[0])},{param($x)$x.files[1].path=$x.files[0].path},{param($x)$x.files[0].sha256='not-a-hash'},{param($x)$x.files[0].path='../unreviewed.ps1'})){$x=Clone $review;&$change $x;Reject {Assert-RHReviewed $x} 'reviewed source rejection'}
$pin=[pscustomobject]@{schemaVersion=1;kind='native-reconstruction-request-pin';runId=$run;requestSha256=$requestHash;requestLength=4096;probeResultSha256=('5'*64);inputs=@(0..9|ForEach-Object{[pscustomobject]@{path=('D:\code\ntfs2refs\.lab\proof\'+$_+'.json');length=128;sha256=('6'*64)}});currentDeviceStateVerified=$false;externalAttestationsPromotedToWriteAuthority=$false;nativeOperationInvoked=$false;conversionQualified=$false;bootQualified=$false}
Assert-RHPin $pin $run $requestHash;$script:checks++
foreach($change in @({param($x)$x.runId='c'*32},{param($x)$x.requestSha256='8'*64},{param($x)$x.inputs=@($x.inputs[0])},{param($x)$x.inputs[1].path=$x.inputs[0].path},{param($x)$x.inputs[0].length=2MB+1},{param($x)$x.inputs[0].length='128'},{param($x)$x.requestLength=0},{param($x)$x.requestLength=128KB+1},{param($x)$x.schemaVersion='1'})){$x=Clone $pin;&$change $x;Reject {Assert-RHPin $x $run $requestHash} 'provenance rejection'}
foreach($name in @('currentDeviceStateVerified','externalAttestationsPromotedToWriteAuthority','nativeOperationInvoked','conversionQualified','bootQualified')){foreach($value in @($true,'false',$null)){$x=Clone $pin;$x.$name=$value;Reject {Assert-RHPin $x $run $requestHash} 'provenance boolean refusal'}}
function Prior([string]$Op){[pscustomobject]@{schemaVersion=1;kind='native-reconstruction-host';status='native-phase-checkpointed';phase='complete';runId=$run;phaseId=$phase;operation=$Op;requestSha256=$requestHash;requestPinSha256=$pinHash;ticketSha256=$ticketHash;vmId='eebbfd4e-d964-4aaf-a6e6-5603fb9b6c4c';baselineId='eda059b3-6d50-46bb-bdf4-018b99b5b34f';phaseExported=$true;ticketExported=$true;cleanShutdown=$true;outcomeCheckpointCreated=$true;baselineRestored=$true;memoryRestored=$true;nativeResultVerified=$true;transportCompletionUnknown=$false;guestOperationUnknown=$false;sessionPreserved=$false;conversionQualified=$false;nativeReportSha256=('6'*64);processResultSha256=('7'*64);outcomeCheckpointId='11111111-2222-3333-aabb-123456789abc';outcomeCheckpointName=('reconstruct-'+$Op+'-'+$phase)}}
foreach($next in @('prepare','apply','resume','rollback','handoff')){foreach($old in @('prepare','apply','resume','rollback','handoff')){$p=Prior $old;$good=($next-ceq'apply'-and$old-cin@('prepare','rollback'))-or($next-ceq'resume'-and$old-cin@('prepare','apply','resume'))-or($next-cin@('rollback','handoff')-and$old-cin@('apply','resume'));if($good){Assert-RHPrior $p $run $requestHash $pinHash $ticketHash $next;$script:checks++}else{Reject {Assert-RHPrior $p $run $requestHash $pinHash $ticketHash $next} 'illegal predecessor'}}}
foreach($change in @({param($x)$x.status='failed-preserved'},{param($x)$x.phase='export-phase'},{param($x)$x.ticketSha256='8'*64},{param($x)$x.requestSha256='8'*64},{param($x)$x.requestPinSha256='8'*64},{param($x)$x.runId='c'*32},{param($x)$x.outcomeCheckpointName='wrong'},{param($x)$x.outcomeCheckpointId=[guid]::Empty.ToString()},{param($x)$x.schemaVersion='1'})){$x=Prior apply;&$change $x;Reject {Assert-RHPrior $x $run $requestHash $pinHash $ticketHash handoff} 'bad prior proof'}
foreach($name in @('phaseExported','ticketExported','cleanShutdown','outcomeCheckpointCreated','baselineRestored','memoryRestored','nativeResultVerified','transportCompletionUnknown','guestOperationUnknown','sessionPreserved','conversionQualified')){foreach($value in @('false',$null)){$x=Prior apply;$x.$name=$value;Reject {Assert-RHPrior $x $run $requestHash $pinHash $ticketHash handoff} 'unknown prior completion'}}
$files=@(foreach($name in @('lab-native-reconstruct.exe','request.json','result.json','result.intent.json','process-intent.json','process-started.json','process-result.json','reconstruct.stdout','reconstruct.stderr')){[pscustomobject]@{name=$name;length=$(if($name-like'reconstruct.*'){0}else{128});sha256=('8'*64);attributes='Archive'}})
Assert-RHArtifacts $files $true;$script:checks++;Assert-RHArtifacts @($files[0]) $false;$script:checks++
Reject {Assert-RHArtifacts @($files[0]) $true} 'incomplete success artifacts'
foreach($change in @({param($x)$x[0].name='journal.bin'},{param($x)$x[0].length=16MB+1},{param($x)$x[0].length=0},{param($x)$x[1].length=0.5},{param($x)$x[1].length='128'},{param($x)$x[1].length=-1},{param($x)$x[2].attributes='ReparsePoint'},{param($x)$x[2].sha256='X'*64},{param($x)$x[3].name=$x[2].name},{param($x)$x[7].length=64KB+1})){$x=Clone $files;&$change $x;Reject {Assert-RHArtifacts $x $true} 'bad artifact bounds/coverage'}
function Process([string]$Op,[string]$Stage){
 $args=@($Op,'--request',($caseRoot+'\request.json'),'--request-sha256',$requestHash,'--journal',('J:\ntfs2refs-shadow\'+$run+'\reconstruction.journal'),'--ticket',('C:\ntfs2refs\native-reconstruct\'+$run+'\ticket.json'),'--output',($caseRoot+'\result.json'));if($Op-cne'prepare'){$args+=@('--ticket-sha256',$ticketHash)}
 $done=$Stage-ceq'result';$started=$Stage-cne'intent'
 [pscustomobject]@{schemaVersion=1;kind='native-reconstruction-process';runId=$run;phaseId=$phase;operation=$Op;requestSha256=$requestHash;binarySha256=$binaryHash;independentTicketSha256=$(if($Op-ceq'prepare'){''}else{$ticketHash});arguments=$args;timeoutSeconds=3600;onlineTransitionRequested=$false;conversionQualified=$false;statePreservationRequired=$true;completionKnown=$done;nativeResultVerified=$done;launchAttempted=$started;processIntentPersisted=$done;exitCode=$(if($done){0}else{$null});processId=$(if($started){42}else{$null});ticketSha256=$(if($done){$ticketHash}else{$null});status=$(if($done){'native-reconstruction-phase-verified-disks-offline'}else{'preflight'});artifacts=$(if($done){@($files|Where-Object name -CIn @('result.json','result.intent.json','reconstruct.stdout','reconstruct.stderr'))}else{@()})}
}
foreach($op in @('prepare','apply','resume','rollback','handoff')){Assert-RHProcess (Process $op result) (Process $op intent) (Process $op started) $request $run $phase $op $requestHash $binaryHash $ticketHash 3600;$script:checks++}
foreach($change in @({param($x)$x.completionKnown=$false},{param($x)$x.completionKnown='true'},{param($x)$x.exitCode=$null},{param($x)$x.exitCode='0'},{param($x)$x.exitCode=1},{param($x)$x.nativeResultVerified=$false},{param($x)$x.processId='42'},{param($x)$x.processId=41},{param($x)$x.ticketSha256='9'*64},{param($x)$x.requestSha256='9'*64},{param($x)$x.binarySha256='9'*64},{param($x)$x.phaseId='c'*32},{param($x)$x.operation='handoff'},{param($x)$x.arguments[0]='handoff'},{param($x)$x.timeoutSeconds=1},{param($x)$x.timeoutSeconds='3600'},{param($x)$x.onlineTransitionRequested=$true},{param($x)$x.processIntentPersisted=$false},{param($x)$x.artifacts=@($x.artifacts[0])})){$x=Process apply result;&$change $x;Reject {Assert-RHProcess $x (Process apply intent) (Process apply started) $request $run $phase apply $requestHash $binaryHash $ticketHash 3600} 'invalid native process outcome'}
$x=Process apply intent;$x.processId=42;Reject {Assert-RHProcess (Process apply result) $x (Process apply started) $request $run $phase apply $requestHash $binaryHash $ticketHash 3600} 'prelaunch already started'
$x=Process apply started;$x.completionKnown=$true;Reject {Assert-RHProcess (Process apply result) (Process apply intent) $x $request $run $phase apply $requestHash $binaryHash $ticketHash 3600} 'started already complete'
function NativeIntent([string]$Op){[pscustomobject]@{schema_version=1;kind='native-reconstruction-intent';operation=$Op;request_sha256=$requestHash;request=(Clone $request);request_file=[pscustomobject]@{test='file'};ticket_path=('C:\ntfs2refs\native-reconstruct\'+$run+'\ticket.json');independent_ticket_sha256=$(if($Op-ceq'prepare'){$null}else{$ticketHash});journal_path=('J:\ntfs2refs-shadow\'+$run+'\reconstruction.journal');phase='before-journal-open';may_modify_journal_after_this_intent=$true;may_issue_target_payload_writes_after_this_intent=($Op-cin@('apply','resume','rollback'));online_transition_allowed=$false;conversion_qualified=$false;boot_qualified=$false}}
$cli=[pscustomobject]@{request_file=[pscustomobject]@{test='file'}}
foreach($op in @('prepare','apply','resume','rollback','handoff')){Assert-RHNativeIntent (NativeIntent $op) $cli $request $op $requestHash $run $ticketHash;$script:checks++}
foreach($change in @({param($x)$x.phase='after-write'},{param($x)$x.operation='handoff'},{param($x)$x.request_sha256='8'*64},{param($x)$x.ticket_path='J:\ticket.json'},{param($x)$x.journal_path='C:\journal'},{param($x)$x.independent_ticket_sha256='8'*64},{param($x)$x.may_modify_journal_after_this_intent=$false},{param($x)$x.may_issue_target_payload_writes_after_this_intent=$false},{param($x)$x.online_transition_allowed=$true},{param($x)$x.request_file.test='other'})){$x=NativeIntent apply;&$change $x;Reject {Assert-RHNativeIntent $x $cli $request apply $requestHash $run $ticketHash} 'native durable intent mismatch'}
# Reuse only named reviewed function definitions, never top-level invocation.
$probeBytes=[IO.File]::ReadAllBytes((Join-Path $workspace 'scripts\Invoke-LabRetainedNativeProbe.ps1'))
Import-RHFunctions $probeBytes @('Write-RetainedProbeJson','Copy-RetainedProbePinned','Read-RetainedProbePinned','Assert-RetainedProbeBoolean','Assert-RetainedProbeCheckpoint','Assert-RetainedProbeArtifacts','Set-RetainedProbeReplyState','Assert-RetainedProbeReply','Assert-RetainedProbeAttachment','Read-RetainedProbeExport','Save-RetainedProbeProgress','Invoke-RetainedProbeCommand','Open-RetainedProbeSession','Assert-RetainedProbeCurrent','Copy-RetainedProbeGuestSources','Restore-RetainedProbeShadow','Stop-RetainedProbeGuest','New-RetainedProbeCheckpoint');$script:checks++
$script:guestOperationUnknown=$false;$script:guestPhaseInFlight=$true;Set-RetainedProbeReplyState ([pscustomobject]@{OperationCompletionKnown=$false});Check ($script:guestOperationUnknown-and-not$script:guestPhaseInFlight) 'unknown completion propagates'
$script:guestOperationUnknown=$false;$script:guestPhaseInFlight=$true;Reject {Set-RetainedProbeReplyState ([pscustomobject]@{Status='success'})} 'missing completion refuses';Check $script:guestOperationUnknown 'missing completion marks unknown'
$script:transportUnknown=$true;Reject {Stop-RetainedProbeGuest 'unused'} 'unknown command forbids shutdown'
$script:transportUnknown=$false;$script:guestOperationUnknown=$true;Reject {Stop-RetainedProbeGuest 'unused'} 'unknown native operation forbids shutdown'
$script:guestOperationUnknown=$false;$script:guestPhaseInFlight=$true;Reject {Stop-RetainedProbeGuest 'unused'} 'in-flight native phase forbids shutdown'
$text=[IO.File]::ReadAllText($path)
Check ($text.IndexOf('$currentSources=@(')-lt$text.IndexOf('Invoke-LabAction -Action Start')) 'archive before VM start'
Check ($text.IndexOf('$record.nativeResultVerified=$true')-lt$text.IndexOf("`$script:phase='clean-shutdown'")) 'validated native result before shutdown'
Check ($text.IndexOf('$record.ticketExported=$true')-lt$text.IndexOf("`$script:phase='clean-shutdown'")) 'ticket export before shutdown'
Check ($text.IndexOf('$record.outcomeCheckpointCreated=$true')-lt$text.IndexOf("`$script:phase='restore-baseline'")) 'saved phase checkpoint before baseline restore'
Check ([regex]::Matches($text,"& 'C:\\ntfs2refs\\guest\\Invoke-GuestNativeReconstruct.ps1'").Count-eq1) 'one reconstruction dispatch only'
$catches=@($ast.FindAll({param($n)$n-is[Management.Automation.Language.CatchClauseAst]},$true));Check (@($catches|Where-Object{$_.Extent.Text-match'Stop-RetainedProbeGuest|Invoke-LabAction|Remove-PSSession|Set-VMMemory'}).Count-eq0) 'no failure cleanup or restore'
foreach($op in @('prepare','apply','resume','rollback','handoff')){$what=&$path -Operation $op -WhatIf;Check ($what.DryRun-and-not$what.AutomaticPhaseProgression-and-not$what.ConversionQualified-and$what.Operation-ceq$op) 'WhatIf returns before any host/VM import'}
Write-Output ('Native reconstruction host: '+$script:checks+' pure/schema/state/WhatIf checks passed; no VM, device or file writes.')
